<script setup lang="ts">
/**
 * GENESIS VIEWPORT
 * =================
 *
 * This is where the reality engine renders.
 *
 * The viewport contains:
 * - Wave function collapse for scene precipitation
 * - Phenomenological NPC interactions
 * - Combat manifold
 * - Real-time simulation state
 *
 * Everything outside this viewport is "normal" Vue.
 * Everything inside is powered by the Genesis engine.
 */

import { ref, onMounted, onUnmounted, defineEmits } from 'vue'

interface Props {
  campaignId: string
  sessionId?: string
}

const props = defineProps<Props>()

const emit = defineEmits<{
  (e: 'exit'): void
  (e: 'error', error: Error): void
}>()

// Viewport state
const isInitialized = ref(false)
const isLoading = ref(true)
const error = ref<string | null>(null)

// Scene state (from precipitation)
const currentScene = ref<{
  location: string
  description: string
  npcsPresent: string[]
  ambiance: string
} | null>(null)

// Initialize the Genesis engine
async function initializeEngine() {
  isLoading.value = true
  error.value = null

  try {
    // TODO: Connect to backend Genesis engine
    // This will:
    // 1. Fetch current campaign state
    // 2. Initialize wave function for scene possibilities
    // 3. Connect to simulation bridge for NPC phenomenology
    // 4. Set up real-time sync

    await new Promise(resolve => setTimeout(resolve, 1000)) // Simulated init

    currentScene.value = {
      location: 'The Yawning Portal',
      description: 'The famous tavern in Waterdeep. Adventurers gather around tables, and the massive well in the center descends into Undermountain.',
      npcsPresent: ['Durnan', 'A mysterious cloaked figure'],
      ambiance: 'Warm firelight, the clink of mugs, and distant rumbles from below.',
    }

    isInitialized.value = true
  } catch (e) {
    error.value = e instanceof Error ? e.message : 'Failed to initialize Genesis'
    emit('error', e instanceof Error ? e : new Error(String(e)))
  } finally {
    isLoading.value = false
  }
}

function handleExit() {
  emit('exit')
}

onMounted(() => {
  initializeEngine()
})

onUnmounted(() => {
  // Cleanup Genesis engine connections
  isInitialized.value = false
})
</script>

<template>
  <div class="genesis-viewport">
    <!-- Loading state -->
    <div v-if="isLoading" class="viewport-loading">
      <div class="loader">
        <div class="loader-ring"></div>
        <p>Initializing reality engine...</p>
      </div>
    </div>

    <!-- Error state -->
    <div v-else-if="error" class="viewport-error">
      <h2>Engine Error</h2>
      <p>{{ error }}</p>
      <button class="btn" @click="initializeEngine">Retry</button>
      <button class="btn btn-ghost" @click="handleExit">Exit</button>
    </div>

    <!-- Active gameplay -->
    <div v-else-if="isInitialized && currentScene" class="viewport-active">
      <!-- Exit button -->
      <button class="exit-btn" @click="handleExit" title="Exit Session">
        &times;
      </button>

      <!-- Scene display -->
      <div class="scene">
        <header class="scene-header">
          <h1>{{ currentScene.location }}</h1>
        </header>

        <div class="scene-description">
          <p>{{ currentScene.description }}</p>
          <p class="ambiance">{{ currentScene.ambiance }}</p>
        </div>

        <div class="scene-npcs" v-if="currentScene.npcsPresent.length">
          <h3>Present</h3>
          <ul>
            <li v-for="npc in currentScene.npcsPresent" :key="npc">{{ npc }}</li>
          </ul>
        </div>
      </div>

      <!-- Action bar -->
      <div class="action-bar">
        <input
          type="text"
          class="action-input"
          placeholder="What do you do?"
        />
        <button class="btn btn-primary">Act</button>
      </div>

      <!-- Debug info (dev only) -->
      <div class="debug-panel">
        <details>
          <summary>Genesis Debug</summary>
          <pre>Campaign: {{ campaignId }}
Session: {{ sessionId || 'none' }}
Engine: initialized
Scene: precipitated</pre>
        </details>
      </div>
    </div>
  </div>
</template>

